    section("وقت‌های مشاوره و ملاقات","زمان و نام مراجعه‌کننده");List<OfficeDb.AppointmentRecord> list=db.appointments(date);if(list.isEmpty())page.addView(empty("قراری ثبت نشده است."));else for(OfficeDb.AppointmentRecord a:list)page.addView(appointmentCard(a));
    section("کارها و مهلت‌های کاری","برنامه‌های ثبت شده در این روز");List<OfficeDb.TaskRecord> tasks=db.tasksForDate(date);if(tasks.isEmpty())page.addView(empty("کاری ثبت نشده است."));else for(OfficeDb.TaskRecord t:tasks)page.addView(taskCard(t));
    section("مهلت‌های پرونده در این روز","مهلت نهایی پرونده");for(OfficeDb.DeadlineRecord d:db.deadlines(null,true))if(date.equals(d.dueDate))page.addView(deadlineCard(d));
