  void caseAttachments(OfficeDb.CaseRecord c){clear("پیوست‌های پرونده",c.title+" · PDF و تصویر");detailBack=()->caseDetail(c);TextView add=action("+ افزودن PDF یا تصویر");add.setOnClickListener(v->{pendingAttachmentCaseId=c.id;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","image/*"});i.addCategory(Intent.CATEGORY_OPENABLE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,ATTACH);});page.addView(add);List<OfficeDb.CaseAttachmentRecord> rows=db.caseAttachments(c.id);if(rows.isEmpty())page.addView(empty("پیوستی ثبت نشده است."));else for(OfficeDb.CaseAttachmentRecord x:rows){View card=info(x.name,"نوع: "+safe(x.mime)+" · زمان ثبت: "+safe(x.createdAt)+"\nبرای باز کردن لمس کنید؛ برای حذف لمس طولانی کنید.");card.setOnClickListener(v->openAttachment(x));card.setOnLongClickListener(v->{confirmImportantDelete("پیوست «"+x.name+"»","فقط ارتباط فایل با پرونده به سطل حذف منتقل می‌شود؛ فایل اصلی دستگاه حذف نمی‌شود.",()->{db.deleteCaseAttachment(x.id);caseAttachments(c);});return true;});page.addView(card);}}
