  long nonNegativeMoney(String raw){if(blank(raw))return 0;long n=Long.parseLong(JalaliDate.asciiDigits(raw.replace(",","").replace("٬","").trim()));if(n<0)throw new IllegalArgumentException("مبلغ منفی معتبر نیست");return n;}
  long positiveMoney(String raw){long n=Long.parseLong(JalaliDate.asciiDigits(raw.replace(",","").replace("٬","").trim()));if(n<=0)throw new IllegalArgumentException("مبلغ باید مثبت باشد");return n;}

