  void backup(){clear("پشتیبان‌گیری امن","انتقال کنترل‌شده اطلاعات بین گوشی‌ها");page.addView(info("روش امن آفلاین","فایل رمزگذاری‌شده .klo شامل دیتابیس و تنظیمات غیرحساس دفتر است. رمز ورود برنامه، تنظیم بایومتریک و URI محلی عکس/پیوست‌ها منتقل نمی‌شوند. فایل فقط با همان کد بازیابی می‌شود؛ کد را جداگانه منتقل کنید."));EditText code=input("کد بکاپ جدید حداقل ۱۲ کاراکتر؛ برای بازیابی کد فایل قبلی");code.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);TextView export=action("ساخت فایل پشتیبان رمزگذاری‌شده"),restore=action("بازیابی فایل پشتیبان در این گوشی");export.setOnClickListener(v->{if(code.length()<12){toast("برای بکاپ جدید، کد حداقل ۱۲ کاراکتر باشد");return;}pendingCode=code.getText().toString();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"دفتر-وکالت-"+JalaliDate.today().value().replace('/','-')+".klo");startActivityForResult(i,EXPORT);});restore.setOnClickListener(v->{if(code.length()<6){toast("ابتدا کد فایل را وارد کنید");return;}pendingCode=code.getText().toString();new AlertDialog.Builder(this).setTitle("تأیید بازیابی").setMessage("اطلاعات فعلی با محتوای فایل جایگزین می‌شود. بهتر است ابتدا از وضعیت فعلی پشتیبان بگیرید. ادامه می‌دهید؟").setNegativeButton("خیر",null).setPositiveButton("ادامه",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}).show();});page.addView(code);page.addView(export);page.addView(restore);}
  @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){if(req==ATTACH)pendingAttachmentCaseId=null;return;}Uri uri=data.getData();try{if(req==PHOTO||req==LOGO){getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);prefs.edit().putString(req==PHOTO?"photo":"logo",uri.toString()).apply();lawyer();}else if(req==ATTACH){if(pendingAttachmentCaseId==null)throw new IllegalStateException("پرونده پیوست مشخص نیست");getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);String mime=getContentResolver().getType(uri);db.addCaseAttachment(pendingAttachmentCaseId,displayName(uri),mime,uri.toString());Long caseId=pendingAttachmentCaseId;for(OfficeDb.CaseRecord c:db.cases(null,"همه",null))if(c.id==caseId){caseAttachments(c);break;}}else if(req==EXPORT){byte[] bytes=SecureBackup.encrypt(exportBundle(),pendingCode);try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(bytes);}toast("پشتیبان رمزگذاری‌شده ذخیره شد");}else if(req==IMPORT){importBundle(SecureBackup.decrypt(readAll(uri),pendingCode));ReminderReceiver.schedule(this);toast("اطلاعات و تنظیمات غیرحساس بازیابی شد");recreate();}}catch(Exception e){new AlertDialog.Builder(this).setTitle("عملیات انجام نشد").setMessage((req==ATTACH?"افزودن پیوست انجام نشد.":"کد نادرست است یا فایل معتبر نیست.")+"\n\n"+e.getClass().getSimpleName()).setPositiveButton("باشه",null).show();}finally{pendingCode=null;pendingAttachmentCaseId=null;}}
  String exportBundle()throws Exception{JSONObject root=new JSONObject();root.put("format","KLO-BUNDLE-1");root.put("app_version",BuildConfig.VERSION_NAME);root.put("database",new JSONObject(db.exportJson()));JSONObject profile=new JSONObject();String[] stringKeys={"name","lawyer_level","professional_body","center","bar_branch","license","national_id","province","city","phone","office_phone","address","website","theme_id","categories","subjects","work_actions","personal_categories","deadline_types","sms_templates","instagram_url","telegram_url"};for(String key:stringKeys)if(prefs.contains(key))profile.put(key,prefs.getString(key,""));profile.put("font_scale",prefs.getFloat("font_scale",1f));profile.put("keep_screen_on",prefs.getBoolean("keep_screen_on",false));profile.put("notifications_enabled",prefs.getBoolean("notifications_enabled",true));profile.put("profile_complete",prefs.getBoolean("profile_complete",false));root.put("profile",profile);return root.toString();}
  void importBundle(String json)throws Exception{JSONObject root=new JSONObject(json);if(!"KLO-BUNDLE-1".equals(root.optString("format"))){db.importJson(json);return;}db.importJson(root.getJSONObject("database").toString());JSONObject profile=root.optJSONObject("profile");if(profile==null)return;SharedPreferences.Editor edit=prefs.edit();String[] stringKeys={"name","lawyer_level","professional_body","center","bar_branch","license","national_id","province","city","phone","office_phone","address","website","theme_id","categories","subjects","work_actions","personal_categories","deadline_types","sms_templates","instagram_url","telegram_url"};for(String key:stringKeys)if(profile.has(key))edit.putString(key,profile.optString(key,""));edit.putFloat("font_scale",(float)profile.optDouble("font_scale",1));edit.putBoolean("keep_screen_on",profile.optBoolean("keep_screen_on",false));edit.putBoolean("notifications_enabled",profile.optBoolean("notifications_enabled",true));edit.putBoolean("profile_complete",profile.optBoolean("profile_complete",false));edit.apply();}
