  TextView tab(String s,boolean on){TextView t=txt(s,13,on?ON_PRIMARY:BLUE);t.setGravity(Gravity.CENTER);t.setPadding(dp(7),dp(11),dp(7),dp(11));t.setBackground(round(on?BLUE:CARD,12));margin(t,3,0,3,0);return t;}
