  TextView action(String s){TextView t=txt(s,13,BLUE);t.setGravity(Gravity.CENTER);t.setPadding(dp(10),dp(13),dp(10),dp(13));t.setBackground(round(Color.WHITE,12));margin(t,3,5,3,5);return t;}
  TextView empty(String s){TextView t=txt(s,13,MUTED);t.setGravity(Gravity.CENTER);t.setPadding(dp(10),dp(28),dp(10),dp(28));return t;}
  LinearLayout form(){LinearLayout f=col();f.setPadding(dp(20),dp(8),dp(20),dp(8));return f;} ScrollView scroll(View v){ScrollView s=new ScrollView(this);s.addView(v);return s;}
  EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(14*fontScale);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setSingleLine(true);e.setPadding(dp(10),dp(7),dp(10),dp(7));e.setLayoutParams(lp(-1,dp(55)));return e;} EditText area(String h){EditText e=input(h);e.setSingleLine(false);e.setGravity(Gravity.TOP|Gravity.RIGHT);e.setMinLines(3);e.setLayoutParams(lp(-1,-2));return e;}
  Spinner spinner(String[] a){Spinner s=new Spinner(this);s.setAdapter(themedAdapter(a));s.setPopupBackgroundDrawable(round(CARD,8));s.setLayoutParams(lp(-1,dp(54)));return s;}
  ArrayAdapter<String> themedAdapter(String[] items){return new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,items){@Override public View getView(int p,View c,android.view.ViewGroup parent){return styleSpinner(super.getView(p,c,parent),false);}@Override public View getDropDownView(int p,View c,android.view.ViewGroup parent){return styleSpinner(super.getDropDownView(p,c,parent),true);}};}
  View styleSpinner(View view,boolean dropdown){if(view instanceof TextView){TextView t=(TextView)view;t.setTextColor(INK);t.setTextSize(14*fontScale);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setTextDirection(View.TEXT_DIRECTION_RTL);t.setPadding(dp(12),dp(dropdown?14:8),dp(12),dp(dropdown?14:8));t.setBackgroundColor(dropdown?CARD:Color.TRANSPARENT);}return view;}
  ImageView image(String uri){ImageView i=new ImageView(this);i.setScaleType(ImageView.ScaleType.CENTER_CROP);i.setPadding(dp(4),dp(4),dp(4),dp(4));i.setBackground(round(CARD,14));if(!blank(uri))try{i.setImageURI(Uri.parse(uri));}catch(Exception ignored){}return i;}
  int organizationLogoResource(String body){return body!=null&&body.contains("مرکز وکلا")?R.drawable.logo_judiciary_center:R.drawable.logo_bar_association;}
  int organizationPrintLogoResource(String body){return body!=null&&body.contains("مرکز وکلا")?R.drawable.logo_judiciary_center:R.drawable.logo_bar_association_print;}
  ImageView organizationLogoView(){return organizationLogoView(prefs.getString("professional_body","کانون وکلای دادگستری"));}
  ImageView organizationLogoView(String body){ImageView i=new ImageView(this);i.setScaleType(ImageView.ScaleType.FIT_CENTER);i.setPadding(dp(4),dp(4),dp(4),dp(4));i.setBackground(round(CARD,14));i.setImageResource(organizationLogoResource(body));return i;}
  LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return l;} LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return l;} TextView txt(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z*fontScale);t.setTextColor(c);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setTextDirection(View.TEXT_DIRECTION_RTL);return t;}
  GradientDrawable round(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c==Color.WHITE?CARD:c);g.setCornerRadius(dp(r));return g;} LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w,h);} LinearLayout.LayoutParams weight(){return new LinearLayout.LayoutParams(0,-2,1);} void margin(View v,int l,int t,int r,int b){LinearLayout.LayoutParams p=v.getLayoutParams() instanceof LinearLayout.LayoutParams?(LinearLayout.LayoutParams)v.getLayoutParams():new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(l),dp(t),dp(r),dp(b));v.setLayoutParams(p);} int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
  boolean blank(String s){return s==null||s.trim().isEmpty();} String safe(String s){return blank(s)?"ثبت نشده":s;} long parseMoney(String s){try{return Long.parseLong(s.replace(",","").replace("٬","").trim());}catch(Exception e){return 0;}} String money(long v){return String.format(Locale.US,"%,d ریال",v);} String ymd(int y,int m,int d){return String.format(Locale.US,"%04d/%02d/%02d",y,m,d);} void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();} String esc(String s){if(s==null)return "";return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\n","<br>");}
  String defaultCategories(){return "کیفری\nحقوقی\nانقلاب\nخانواده\nدیوان عدالت اداری\nنظامی\nسایر";} String defaultSubjects(){return "طرح شکایت\nدفاع\nدادخواست\nتجدیدنظرخواهی\nفرجام\nاجرای حکم\nمطالبه وجه\nالزام به ایفای تعهد\nاعتراض به رأی\nاختلاف خانوادگی\nشکایت اداری\nدفاع کیفری\nاختلاف قراردادی\nسایر";} String defaultActions(){return "مطالعه پرونده\nمراجعه به شعبه\nگفتگو با قاضی\nگفتگو با مدیر دفتر\nپیگیری پرونده\nارسال لایحه\nجلسه با موکل\nحضور در جلسه رسیدگی\nمراجعه برای کارشناسی\nسایر";} String defaultPersonalCategories(){return "کار شخصی\nدادگاه\nامور اداری\nکانون وکلا\nمطالعه\nورزش\nاستراحت\nغذا\nخرید\nسفر\nسایر";} String defaultSms(){return "یادآوری جلسه§{موکل} گرامی، زمان جلسه شما یادآوری می‌شود. لطفاً با دفتر هماهنگ فرمایید.\nاطلاع پرونده§{موکل} گرامی، درباره پرونده شما به‌روزرسانی ثبت شده است. لطفاً با دفتر تماس بگیرید.\nیادآوری پرداخت§{موکل} گرامی، لطفاً درباره وضعیت مالی پرونده با دفتر هماهنگ فرمایید.";}
  String[] categoryList(){return lines(prefs.getString("categories",defaultCategories()));} String[] subjectList(){return lines(prefs.getString("subjects",defaultSubjects()));} String[] workActionList(){return lines(prefs.getString("work_actions",defaultActions()));} String[] smsRows(){return lines(prefs.getString("sms_templates",defaultSms()));} String[] withAll(String[] a){String[] b=new String[a.length+1];b[0]="همه";System.arraycopy(a,0,b,1,a.length);return b;} String[] lines(String s){String clean=cleanLines(s);return blank(clean)?new String[]{"سایر"}:clean.split("\n");} String cleanLines(String s){if(s==null)return "";StringBuilder b=new StringBuilder();for(String x:s.split("\\r?\\n")){x=x.trim();if(!x.isEmpty()){if(b.length()>0)b.append('\n');b.append(x);}}return b.toString();}
  String casesText(List<OfficeDb.CaseRecord> list){StringBuilder b=new StringBuilder();for(OfficeDb.CaseRecord c:list)b.append(c.title).append("\nشماره: ").append(safe(c.caseNumber)).append(" | موکل: ").append(safe(c.clientName)).append("\nوضعیت: ").append("active".equals(c.status)?"جاری":"مختومه").append(" | دسته: ").append(safe(c.category)).append(" | موضوع: ").append(safe(c.subject)).append("\nمرجع: ").append(safe(c.authorityType)).append("، ").append(safe(c.province)).append("، ").append(safe(c.judicialCity)).append("\n\n");return b.toString();}
  String clientsText(List<OfficeDb.ClientRecord> list){StringBuilder b=new StringBuilder();for(OfficeDb.ClientRecord c:list)b.append(c.name).append("\nتلفن: ").append(safe(c.phone)).append(" | کد ملی: ").append(safe(c.nationalId)).append("\nنشانی: ").append(safe(c.address)).append("\nپرونده‌ها: ").append(c.caseCount).append(" (جاری: ").append(c.activeCount).append(")\n\n");return b.toString();}
  String workLogsText(List<OfficeDb.WorkLogRecord> list){StringBuilder b=new StringBuilder();for(OfficeDb.WorkLogRecord x:list)b.append(safe(x.date)).append(" | ").append(safe(x.type)).append("\nپرونده: ").append(safe(x.caseTitle)).append(" | موکل: ").append(safe(x.clientName)).append("\n").append(safe(x.description)).append("\n\n");return b.toString();}
  String strongHash(String pass){try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);PBEKeySpec spec=new PBEKeySpec(pass.toCharArray(),salt,150000,256);byte[] digest=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();spec.clearPassword();return "pbkdf2$"+Base64.encodeToString(salt,Base64.NO_WRAP)+"$"+Base64.encodeToString(digest,Base64.NO_WRAP);}catch(Exception e){throw new IllegalStateException("ذخیره رمز امن ممکن نیست",e);}}
  boolean verifyPassword(String pass){String saved=prefs.getString("password_hash","");try{if(saved.startsWith("pbkdf2$")){String[] parts=saved.split("\\$");if(parts.length!=3)return false;byte[] salt=Base64.decode(parts[1],Base64.NO_WRAP),expected=Base64.decode(parts[2],Base64.NO_WRAP);PBEKeySpec spec=new PBEKeySpec(pass.toCharArray(),salt,150000,expected.length*8);byte[] actual=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();spec.clearPassword();return MessageDigest.isEqual(actual,expected);}if(!saved.isEmpty()&&MessageDigest.isEqual(hash(pass).getBytes("UTF-8"),saved.getBytes("UTF-8"))){prefs.edit().putString("password_hash",strongHash(pass)).apply();return true;}}catch(Exception ignored){}return false;}
  String hash(String s){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));StringBuilder b=new StringBuilder();for(byte x:bytes)b.append(String.format(Locale.US,"%02x",x));return b.toString();}catch(Exception e){throw new IllegalStateException("تأیید رمز ممکن نیست",e);}}
  void errorScreen(Throwable e){LinearLayout f=col();f.setGravity(Gravity.CENTER);f.setPadding(dp(24),dp(24),dp(24),dp(24));f.addView(txt("برنامه با خطا روبه‌رو شد\n\n"+e.getClass().getSimpleName()+": "+safe(e.getMessage()),15,RED));setContentView(f);safeArea(f);}
